import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Wiring .hnl modules into HandlNativeLint and HandlNativeRewrite","description":"","frontmatter":{"title":"Wiring `.hnl` modules into `HandlNativeLint` and `HandlNativeRewrite`","type":"adr","date":"2026-09-14T00:00:00.000Z","status":"proposed","status_note":"Proposed"},"headers":[],"relativePath":"handl/project/adrs/0100-handl-natives-wire.md","filePath":"vendored/handl/project/adrs/0100-handl-natives-wire.md"}'),a={name:`handl/project/adrs/0100-handl-natives-wire.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="wiring-hnl-modules-into-handlnativelint-and-handlnativerewrite" tabindex="-1">Wiring <code>.hnl</code> modules into <code>HandlNativeLint</code> and <code>HandlNativeRewrite</code> <a class="header-anchor" href="#wiring-hnl-modules-into-handlnativelint-and-handlnativerewrite" aria-label="Permalink to “Wiring .hnl modules into HandlNativeLint and HandlNativeRewrite”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><code>HandlNativeLint</code> (<code>plugin-lib-handl/src/lint.rs</code>) and <code>HandlNativeRewrite</code> (<code>plugin-lib-handl/src/transform.rs</code>) already implement the adapters that let lint and transform rules dispatch into pure-handl functions via the <code>handl:&lt;mod&gt;.&lt;fn&gt;</code> name prefix. They are tested in unit tests but are not wired into the production hosts (<code>plugin-ext-lint</code>, <code>host-tooling</code>, <code>host-cli</code> <code>transform</code>, <code>plugin-engine-transform-rewrite</code>).</p><p>The canonical kit (<code>handl-kit-canonical</code>) builds a <code>ModuleRegistry</code> of every stdlib module, many of which are <code>.hnl</code>-backed <code>HandlModule</code>s. The same <code>HandlModule</code>s must be made available to <code>HandlNativeLint</code> and <code>HandlNativeRewrite</code> so that <code>lints.yaml</code> rules with <code>check: !Native &quot;handl:...&quot;</code> and <code>transforms.yaml</code> rules with <code>rule: !Native &quot;handl:...&quot;</code> resolve at runtime instead of reporting &quot;unknown native&quot;.</p><p>A historical implementation existed on the <code>wire/handl-natives</code> branch. That branch is now stale: it was written before the current <code>Kit</code>/<code>build_stdlib_registry</code> shape (with per-module <code>want</code> filters, <code>get_module</code> caching, and the removal of <code>plugin-lib-rand-native</code> / <code>plugin-lib-time-native</code> / <code>plugin-engine-typecheck-nbe</code>), so it cannot be merged mechanically.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Rewrite the wiring as a clean, modern implementation:</p><ol><li>Extend <code>handl-kit-canonical</code> to track every <code>.hnl</code>-backed <code>HandlModule</code> it registers, alongside the existing <code>ModuleRegistry</code>. The collection can live as a <code>HandlModules</code> struct paired with the registry (<code>KitModules</code>).</li><li>Expose <code>Kit::handl_lint_adapter()</code> and <code>Kit::handl_rewrite_adapter()</code> methods that build fully populated <code>HandlNativeLint</code> and <code>HandlNativeRewrite</code> instances from the tracked <code>HandlModule</code>s.</li><li>Wire the lint adapter into <code>plugin-ext-lint::lint_engine</code> and <code>host-tooling::diagnose</code> by adding it as a resolver on the existing <code>NativeLintRegistry</code>.</li><li>Wire the rewrite adapter into <code>host-cli</code> <code>transform</code> by layering it over the <code>desugar.*</code> native registry.</li><li>Add a <code>RewriteEngine::with_desugar_and_handl_natives</code> constructor that installs both the handl-native registry and the <code>desugar</code> fallback table used by kind-based dispatch.</li></ol><p>The implementation must use current APIs only: <code>ModuleRegistry::register_arc</code>, <code>HandlNativeLint::with_module_arc</code>, <code>HandlNativeRewrite::with_module_arc</code>/<code>with_fallback</code>, <code>NativeLintRegistry::add_resolver</code>, and the existing <code>Kit::build_kit</code> flow.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>.hnl</code>-authored lint and transform rules shipped in <code>lints.yaml</code> and <code>transforms.yaml</code> become runnable in the CLI and host tooling.</li><li><code>handl-kit-canonical</code> becomes the single source of truth for which <code>.hnl</code> modules are available to handl-native adapters.</li><li>The stale <code>wire/handl-natives</code> branch can be deleted once the ADR is accepted and the implementation is merged; the branch itself is not a safe merge target.</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};